from pathlib import Path
from playwright.sync_api import sync_playwright
import json
R=Path(__file__).resolve().parents[2];root=R/'launch/attachment-rim-repairs/finish/iceland/verified'
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True);p=b.new_page(viewport={'width':1440,'height':1080},reduced_motion='reduce',offline=True);p.goto((root/'iceland-backright-v10.html').as_uri());p.wait_for_function('pilot.ready');p.locator('#open').click();p.wait_for_function('pilot.progress===1');p.wait_for_timeout(150)
 report=p.evaluate('''(()=>{let pts=[[651,574],[809,503],[841,515],[870,526],[890,537],[610,272],[621,298]],V=pilot.root.position.constructor,rect=document.querySelector('canvas').getBoundingClientRect(),result=[];pilot.root.updateMatrixWorld(true);for(let [x,y]of pts){let hits=[];for(let dx of [-2,0,2])for(let dy of [-2,0,2]){let origin=pilot.camera.position.clone(),dir=new V(((x+dx-rect.x)/rect.width)*2-1,-((y+dy-rect.y)/rect.height)*2+1,.5).unproject(pilot.camera).sub(origin).normalize(),best=null;pilot.root.traverse(o=>{if(!o.isMesh)return;let pos=o.geometry.attributes.position,idx=o.geometry.index,count=idx?idx.count:pos.count;for(let i=0;i<count;i+=3){let a=new V().fromBufferAttribute(pos,idx?idx.getX(i):i).applyMatrix4(o.matrixWorld),bb=new V().fromBufferAttribute(pos,idx?idx.getX(i+1):i+1).applyMatrix4(o.matrixWorld),c=new V().fromBufferAttribute(pos,idx?idx.getX(i+2):i+2).applyMatrix4(o.matrixWorld),e1=bb.sub(a),e2=c.sub(a),h=dir.clone().cross(e2),det=e1.dot(h);if(Math.abs(det)<1e-10)continue;let f=1/det,s=origin.clone().sub(a),u=f*s.dot(h);if(u<0||u>1)continue;let q=s.cross(e1),v=f*dir.dot(q);if(v<0||u+v>1)continue;let t=f*e2.dot(q);if(t>0&&(!best||t<best.distance))best={name:o.name,triangle:i/3,distance:t};}});if(best)hits.push(best);}result.push({pixel:[x,y],hits});}return result})()''')
